-- ApnaGhar database setup. Generated by scripts/build_schema.py.
-- Run in your own Supabase project SQL Editor.
-- Includes migrations 001 through 007; do not also run them separately.


-- BEGIN 001_initial_schema.sql
-- Real Estate AI Agent — Initial Database Schema
-- Run this in Supabase SQL Editor (Dashboard → SQL Editor → New Query)

-- Step 1: Enable pgvector extension
create extension if not exists vector;

-- ============================================================
-- PROPERTIES TABLE
-- Stores enriched property JSON + semantic embeddings
-- ============================================================
create table if not exists properties (
  id            text primary key,                -- e.g. "rag_property_PROP001"
  property_id   text unique,                     -- e.g. "PROP001"
  data          jsonb not null,                  -- full enriched property JSON
  semantic_text text,                            -- text that was embedded
  embedding     vector(384),                     -- all-MiniLM-L6-v2 (384 dims)
  area_name     text,                            -- for fast filtering
  city          text default 'Patna',
  bhk           int,
  price_inr     bigint,
  property_type text,
  status        text default 'available',        -- available | booked | removed
  created_at    timestamptz default now(),
  updated_at    timestamptz default now()
);

-- Index for vector similarity search (cosine distance)
-- Note: Run after inserting data (requires at least 1 row for ivfflat)
-- create index if not exists properties_embedding_idx
--   on properties using ivfflat (embedding vector_cosine_ops) with (lists = 10);

-- Indexes for metadata filtering
create index if not exists properties_city_idx on properties (city);
create index if not exists properties_bhk_idx on properties (bhk);
create index if not exists properties_price_idx on properties (price_inr);
create index if not exists properties_area_idx on properties (area_name);
create index if not exists properties_status_idx on properties (status);

-- ============================================================
-- BROKERS TABLE
-- ============================================================
create table if not exists brokers (
  id                text primary key,            -- e.g. "BROKER001"
  name              text not null,
  phone             text,
  email             text,
  telegram_chat_id  text,                        -- for Telegram notifications
  areas             text[],                      -- list of area names they cover
  is_active         boolean default true,
  created_at        timestamptz default now()
);

-- ============================================================
-- LEADS TABLE
-- Qualified buyer leads
-- ============================================================
create table if not exists leads (
  id              uuid primary key default gen_random_uuid(),
  session_id      text,                          -- links to user conversation
  name            text,
  phone           text,
  email           text,
  budget_min      bigint,
  budget_max      bigint,
  preferred_bhk   int,
  preferred_city  text default 'Patna',
  preferred_area  text,
  interested_property_id text references properties(id),
  broker_id       text references brokers(id),
  status          text default 'new',            -- new | contacted | visit_scheduled | converted | rejected
  notes           text,
  created_at      timestamptz default now(),
  updated_at      timestamptz default now()
);

create index if not exists leads_status_idx on leads (status);
create index if not exists leads_broker_idx on leads (broker_id);

-- ============================================================
-- SESSIONS TABLE
-- Conversation memory per user session
-- ============================================================
create table if not exists sessions (
  session_id    text primary key,               -- telegram chat_id or web session token
  platform      text default 'web',             -- telegram | web | whatsapp
  messages      jsonb default '[]',             -- list of {role, content, timestamp}
  requirements  jsonb default '{}',             -- extracted: city, bhk, budget, amenities etc.
  stage         text default 'discovery',       -- discovery | recommending | lead_capture | done
  updated_at    timestamptz default now()
);

-- ============================================================
-- MEETINGS TABLE
-- Scheduled property visits
-- ============================================================
create table if not exists meetings (
  id                uuid primary key default gen_random_uuid(),
  lead_id           uuid references leads(id),
  broker_id         text references brokers(id),
  property_id       text references properties(id),
  scheduled_at      timestamptz,
  duration_minutes  int default 60,
  status            text default 'pending',     -- pending | confirmed | completed | cancelled | rescheduled
  customer_reminded boolean default false,
  broker_reminded   boolean default false,
  visit_outcome     text,                       -- interested | negotiating | rejected | booked
  notes             text,
  created_at        timestamptz default now(),
  updated_at        timestamptz default now()
);

create index if not exists meetings_scheduled_idx on meetings (scheduled_at);
create index if not exists meetings_status_idx on meetings (status);

-- ============================================================
-- MATCH PROPERTIES FUNCTION
-- Called by the RAG retriever for hybrid search
-- ============================================================
create or replace function match_properties(
  query_embedding   vector(384),
  match_threshold   float    default 0.3,
  match_count       int      default 10,
  filter_city       text     default null,
  filter_max_price  bigint   default null,
  filter_min_price  bigint   default null,
  filter_bhk        int      default null,
  filter_area       text     default null
)
returns table(
  id            text,
  property_id   text,
  data          jsonb,
  semantic_text text,
  similarity    float
)
language sql stable as $$
  select
    p.id,
    p.property_id,
    p.data,
    p.semantic_text,
    1 - (p.embedding <=> query_embedding) as similarity
  from properties p
  where
    p.status = 'available'
    and (filter_city  is null or p.city       = filter_city)
    and (filter_bhk   is null or p.bhk        = filter_bhk)
    and (filter_max_price is null or p.price_inr <= filter_max_price)
    and (filter_min_price is null or p.price_inr >= filter_min_price)
    and (filter_area  is null or replace(p.area_name, ' ', '') ilike '%' || filter_area || '%')
    and 1 - (p.embedding <=> query_embedding) > match_threshold
  order by p.embedding <=> query_embedding
  limit match_count;
$$;

-- ============================================================
-- HELPER: Mark property as booked
-- ============================================================
create or replace function mark_property_booked(prop_id text)
returns void language sql as $$
  update properties set status = 'booked', updated_at = now() where id = prop_id;
$$;

-- END 001_initial_schema.sql


-- BEGIN 002_broker_confirmations.sql
-- Pending broker availability confirmations (two-way WhatsApp scheduling)
create table if not exists broker_confirmations (
  id               uuid primary key default gen_random_uuid(),
  lead_id          uuid references leads(id),
  meeting_id       uuid references meetings(id),
  broker_phone     text not null,
  buyer_name       text,
  buyer_phone      text,
  buyer_session_id text,
  property_id      text,
  proposed_dt      timestamptz,
  proposed_when    text,           -- human-readable "Saturday 21 Jun at 5 pm"
  status           text default 'pending', -- pending | yes | no | rescheduled
  created_at       timestamptz default now()
);

create index if not exists broker_conf_broker_phone_idx on broker_confirmations(broker_phone, status);

-- END 002_broker_confirmations.sql


-- BEGIN 003_storage_setup.sql
-- Server-managed public property assets. The API writes with the service-role key.
insert into storage.buckets (id, name, public)
values
  ('property-images', 'property-images', true),
  ('property-documents', 'property-documents', true)
on conflict (id) do update set public = excluded.public;

do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'storage' and tablename = 'objects'
      and policyname = 'Public read property assets'
  ) then
    create policy "Public read property assets"
    on storage.objects for select
    using (bucket_id in ('property-images', 'property-documents'));
  end if;
end $$;

-- END 003_storage_setup.sql


-- BEGIN 004_customers_and_pipeline.sql
-- ApnaGhar: include customer login and CRM offer fields in normal migrations.
create table if not exists public.customers (
  id uuid primary key default gen_random_uuid(),
  email text unique not null,
  name text,
  phone text,
  google_sub text,
  favourites jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists customers_email_idx on public.customers (email);
alter table public.leads add column if not exists broker_offer text;
alter table public.leads add column if not exists customer_offer text;

-- END 004_customers_and_pipeline.sql


-- BEGIN 005_server_access.sql
-- ApnaGhar uses FastAPI for access control and a server-only service-role key.
-- These tables must never be readable with the browser's Supabase anon key.
alter table public.properties enable row level security;
alter table public.brokers enable row level security;
alter table public.leads enable row level security;
alter table public.sessions enable row level security;
alter table public.meetings enable row level security;
alter table public.customers enable row level security;
alter table public.broker_confirmations enable row level security;

-- Remove the old unrestricted upload/delete policies from migration 002.
drop policy if exists "Brokers can upload property images" on storage.objects;
drop policy if exists "Brokers can delete property images" on storage.objects;

revoke execute on function public.match_properties(vector, double precision, integer, text, bigint, bigint, integer, text) from public, anon, authenticated;
revoke execute on function public.mark_property_booked(text) from public, anon, authenticated;
grant execute on function public.match_properties(vector, double precision, integer, text, bigint, bigint, integer, text) to service_role;
grant execute on function public.mark_property_booked(text) to service_role;

-- END 005_server_access.sql


-- BEGIN 006_patna_defaults.sql
-- ApnaGhar now serves Patna. Only defaults change; historical rows stay unchanged.
alter table public.properties alter column city set default 'Patna';
alter table public.leads alter column preferred_city set default 'Patna';

-- END 006_patna_defaults.sql


-- BEGIN 007_verified_broker_accounts.sql
-- ApnaGhar: admin-reviewed broker accounts. Properties publish immediately.
-- Run once after migrations 001-006. No broker password is stored in public tables.
begin;
alter table public.brokers add column if not exists auth_user_id uuid references auth.users(id) on delete set null;
alter table public.brokers add column if not exists approval_status text not null default 'pending';
alter table public.brokers add column if not exists agency text;
alter table public.brokers add column if not exists verification_reference text;
alter table public.brokers add column if not exists reviewed_at timestamptz;
alter table public.brokers add column if not exists reviewed_by text;
alter table public.brokers alter column is_active set default false;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'brokers_approval_status_check' and conrelid = 'public.brokers'::regclass) then
    alter table public.brokers add constraint brokers_approval_status_check
      check (approval_status in ('pending', 'approved', 'rejected', 'suspended'));
  end if;
end $$;
-- Existing shared-login profiles do not automatically become verified accounts.
update public.brokers set is_active = false where approval_status <> 'approved';
create unique index if not exists brokers_auth_user_idx on public.brokers(auth_user_id) where auth_user_id is not null;
create unique index if not exists brokers_account_email_idx on public.brokers(lower(email)) where auth_user_id is not null;
create unique index if not exists brokers_account_phone_idx on public.brokers(phone) where auth_user_id is not null;
alter table public.properties add column if not exists broker_id text references public.brokers(id);
update public.properties p set broker_id = b.id from public.brokers b
  where p.broker_id is null and p.data #>> '{source_ids,broker_id}' = b.id;
create index if not exists properties_broker_idx on public.properties(broker_id);
create table if not exists public.broker_reviews (
  id uuid primary key default gen_random_uuid(),
  broker_id text not null references public.brokers(id),
  action text not null check (action in ('approved', 'rejected', 'suspended')),
  reviewer text not null,
  note text not null default '',
  created_at timestamptz not null default now()
);
alter table public.broker_reviews enable row level security;
alter table public.brokers enable row level security;
revoke all on public.broker_reviews from anon, authenticated;
grant all on public.broker_reviews to service_role;
create or replace function public.review_broker_application(
  target_broker_id text, next_status text, reviewer_name text, review_note text default ''
) returns jsonb language plpgsql security definer set search_path = public as $$
declare result public.brokers;
begin
  if next_status not in ('approved', 'rejected', 'suspended') then
    raise exception 'Invalid review status';
  end if;
  update public.brokers set approval_status = next_status,
      is_active = (next_status = 'approved'), reviewed_at = now(), reviewed_by = reviewer_name
    where id = target_broker_id and auth_user_id is not null returning * into result;
  if not found then raise exception 'Broker account not found'; end if;
  insert into public.broker_reviews(broker_id, action, reviewer, note)
    values(target_broker_id, next_status, reviewer_name, coalesce(review_note, ''));
  return to_jsonb(result);
end $$;
revoke all on function public.review_broker_application(text, text, text, text) from public, anon, authenticated;
grant execute on function public.review_broker_application(text, text, text, text) to service_role;
commit;

-- END 007_verified_broker_accounts.sql
